// Dev-only stand-in for @deepseek-ai/dsh-tools so the suite runs outside a DSH install.
// It is NOT a behaviour-free identity: it validates exactly what the real registry
// validates at registration time, so a schema mistake fails here rather than at host boot.
//
// Deliberate, documented divergence from the real package, verified probe by probe:
//
//   real.defineTool({ output: { schema: { type: 'json' } } })  -> accepted (it compiles to {})
//   this stand-in for the same input                              -> rejected
//
// The stand-in is stricter on purpose. It exists to catch schema mistakes before host
// boot, and `output.schema: { type: 'json' }` is exactly what the shipped build once
// passed to the registry uncompiled:
//
//   unsupported JSON schema: schema.type must be one of object/array/string/number/integer/boolean/null
//
// If you align this file with production, keep the author DSL rejected — that rejection is
// the fence, not an oversight.
//
// Everything else matches the real package: object schemas must state additionalProperties,
// unknown keywords are refused, and assertSupportedJsonSchema is laxer than defineTool
// (it accepts { type: 'object' } while the compiler does not), which is why the plugin
// always states additionalProperties explicitly.
//
// Kept deliberately in sync with the real package's enforced subset:
//   type / oneOf / properties / required / additionalProperties / items / enum / const
//   + annotations (description, title, default, examples)
export const SUPPORTED_TYPES = ['object', 'array', 'string', 'number', 'integer', 'boolean', 'null']
const SUPPORTED_KEYWORDS = new Set([
  'type',
  'oneOf',
  'properties',
  'required',
  'additionalProperties',
  'items',
  'enum',
  'const',
  'description',
  'title',
  'default',
  'examples',
])

export class JsonSchemaError extends Error {
  constructor(message) {
    super(message)
    this.name = 'JsonSchemaError'
  }
}

function assertNode(node, path) {
  if (node === null || typeof node !== 'object') return
  if (Array.isArray(node)) {
    node.forEach((entry, index) => assertNode(entry, `${path}[${index}]`))
    return
  }
  if (Object.hasOwn(node, 'type')) {
    const type = node.type
    if (Array.isArray(type) || !SUPPORTED_TYPES.includes(type)) {
      throw new JsonSchemaError(`unsupported JSON schema: schema.type must be one of ${SUPPORTED_TYPES.join('/')}`)
    }
  }
  for (const [key, value] of Object.entries(node)) {
    if (!SUPPORTED_KEYWORDS.has(key)) throw new JsonSchemaError(`unsupported JSON schema: ${path}.${key} is not a supported keyword`)
    // `properties` keys are property names, not keywords: recurse into their schemas.
    if (key === 'properties' && value !== null && typeof value === 'object') {
      for (const [property, propertySchema] of Object.entries(value)) assertNode(propertySchema, `${path}.properties.${property}`)
      continue
    }
    // `additionalProperties` may be a boolean, which carries no schema to check.
    if (key === 'additionalProperties' && typeof value === 'boolean') continue
    assertNode(value, `${path}.${key}`)
  }
}

/** Same contract as the real validator: throw on anything outside the enforced subset. */
export function assertSupportedJsonSchema(schema) {
  if (schema === null || typeof schema !== 'object' || Array.isArray(schema)) {
    throw new JsonSchemaError('unsupported JSON schema: a schema must be an object')
  }
  assertNode(schema, 'schema')
  return schema
}

/**
 * The real defineTool compiles the author DSL, which is stricter than the registry's own
 * assertion in one specific way: a compiled object schema must state explicitly whether
 * extra properties are allowed, at the root and in every nested object. The same rule is
 * mirrored here so the stand-in never accepts a definition the real compiler would reject.
 */
function assertCompiledObjectSchema(node, path) {
  if (node === null || typeof node !== 'object') return
  if (Array.isArray(node)) {
    node.forEach((entry, index) => assertCompiledObjectSchema(entry, `${path}[${index}]`))
    return
  }
  if (node.type === 'object' && typeof node.additionalProperties !== 'boolean') {
    throw new JsonSchemaError(`unsupported JSON schema: ${path}.additionalProperties must be explicitly true or false`)
  }
  for (const [key, value] of Object.entries(node)) {
    if (key === 'properties' && value !== null && typeof value === 'object') {
      for (const [property, propertySchema] of Object.entries(value)) assertCompiledObjectSchema(propertySchema, `${path}.properties.${property}`)
      continue
    }
    if (key === 'additionalProperties' && typeof value === 'boolean') continue
    assertCompiledObjectSchema(value, `${path}.${key}`)
  }
}

export function defineTool(definition) {
  if (definition.parameters !== undefined) assertCompiledObjectSchema(definition.parameters, 'parameters')
  if (definition.output?.schema !== undefined) {
    assertSupportedJsonSchema(definition.output.schema)
    assertCompiledObjectSchema(definition.output.schema, 'output.schema')
  }
  return definition
}
